    let output = ActionOutputReady {
        output_slot: SlotIdx::new(0),
        value: vb_core::value::SlotValue::I64(42),
        taint: Taint::Clean,
        encoded_len: 8,
    };

    let result = shard.enqueue(ShardCommand::ActionCompleted { ticket, output });
    assert_eq!(result, Ok(()), "valid ticket must be accepted");
    shard.tick().expect("tick after completion");

    // Verify run state
    let state = shard
        .run_state_get(run)
        .expect("run state must exist after completion");
    let slot_value = state
        .frame
        .read_slot(SlotIdx::new(0))
        .expect("slot 0 must be readable");

    match slot_value {
        vb_core::value::SlotValue::I64(n) => {
            assert_eq!(*n, 42, "slot 0 must contain I64(42)");
        }
        other => panic!("slot 0 contains {:?} instead of I64(42)", other),
    }
}
